   manifest.Repos=append(manifest.Repos,workspaceRepo{RepoKey:foreignKey,LocalPathHint:filepath.Join(t.TempDir(),"foreign")})
   // The first identity lookup runs after the manifest is loaded. Replace its
   // file then: a second load during execution would consume the foreign key.
   changed:=false
   opts.Runner=&workspaceScopeRunner{CommandRunner:opts.Runner,beforeRun:func(){
    if err:=writeWorkspaceManifest(opts.Env,manifest);err!=nil{t.Fatal(err)}
    changed=true
   }}
   response:=mcpScopeCall(t,opts,tool,map[string]any{"workspace":"snapshot","query":"scope"})
   if errObj,ok:=response["error"];ok{t.Fatalf("snapshot rejected: %v",errObj)}
   data,err:=json.Marshal(response);if err!=nil{t.Fatal(err)}
   if !changed || strings.Contains(string(data),foreignKey) || !strings.Contains(string(data),siblingKey){t.Fatalf("execution did not retain validated members: %s",data)}
  })
 }
}
